 ('branch_grooming_rules','pengaturan',null,array['doctor_required'],'refs',null,null,array['branch_id'],array['branch_id'],'[]'::jsonb,false,array['OWNER','ADMIN']),
 -- M05 opening AP/AR import: batch totals only; party names, numbers and notes stay out.
 ('opening_invoice_batches','buku-besar',null,array['ap_count','ap_total','ar_count','ar_total'],'refs',null,null,array['id'],array['branch_id'],
  '[{"entity":"journal_entries","key":"journal_id"}]'::jsonb,false,array['OWNER','ADMIN']),
 ('opening_invoice_lines','buku-besar',null,array['tanggal','jatuh_tempo','outstanding','original_total'],'refs','opening_invoice_batches','batch_id',array['id'],'{}',
  '[{"entity":"opening_invoice_batches","key":"batch_id"},{"entity":"purchase_invoices","key":"purchase_invoice_id"},{"entity":"sales_invoices","key":"sales_invoice_id"}]'::jsonb,false,array['OWNER','ADMIN']),
 -- J04 schedule source: payload/snapshot/config are JSON, so metadata only.
 ('recurring_journal_sources','buku-besar',null,'{}','refs','recurring_journals','schedule_id',array['schedule_id'],array['branch_id'],
  '[{"entity":"recurring_journals","key":"schedule_id"},{"entity":"journal_entries","key":"source_entry_id"}]'::jsonb,true,array['OWNER','ADMIN']),
 -- J03 refund lines under their posted clinic refund (descriptions excluded).
 ('clinic_refund_items','klinik',null,array['qty','amount','restock','kondisi','base_qty','hpp'],'refs','clinic_refunds','refund_id',array['id'],'{}',
  '[{"entity":"clinic_refunds","key":"refund_id"},{"entity":"invoice_items","key":"invoice_item_id"}]'::jsonb,false,array['OWNER','ADMIN']),
 -- K01 addendum: medical text and the frozen original record are never copied.
 ('clinic_record_addenda','klinik',null,'{}','refs','medical_records','medical_record_id',array['id'],'{}',
  '[{"entity":"medical_records","key":"medical_record_id"},{"entity":"invoices","key":"invoice_id"}]'::jsonb,true,array['OWNER','ADMIN']),
 -- K07 inpatient handover/administration evidence and its per-branch input rule.
 ('inpatient_rx_evidence','klinik',null,'{}','refs','inpatient_records','inpatient_record_id',array['id'],array['branch_id'],
  '[{"entity":"inpatient_records","key":"inpatient_record_id"},{"entity":"prescription_items","key":"prescription_item_id"}]'::jsonb,true,array['OWNER','ADMIN']),
 ('inpatient_rx_evidence_settings','klinik',null,array['administration_requires_handover','max_backdate_minutes'],'refs',null,null,array['branch_id'],array['branch_id'],'[]'::jsonb,false,array['OWNER','ADMIN']),
 -- N01 invoice <-> goods receipt link; only the active flag changes afterwards.
 ('purchase_invoice_receipts','pembelian',null,array['active'],'refs','purchase_invoices','invoice_id',array['invoice_id','goods_receipt_id'],'{}',
  '[{"entity":"purchase_invoices","key":"invoice_id"},{"entity":"goods_receipts","key":"goods_receipt_id"}]'::jsonb,false,array['OWNER','ADMIN']),
 -- Q01 claim carries a phone key and has no authenticated reader: retain metadata
 -- under its sale but never expose it through the viewer (as sale_staff_effects).
 ('quest_new_customer_claims','pos',null,'{}','refs','sales','sale_id',array['customer_id'],array['branch_id'],
  '[{"entity":"sales","key":"sale_id"}]'::jsonb,true,'{}')
on conflict (entity) do nothing;

do $$
declare t text;
 new_sources text[]:=array['campaign_codes','payslip_templates','payslip_template_components','employee_payslip_templates',
  'employee_base_salaries','service_commission_policies','branch_grooming_rules','opening_invoice_batches','opening_invoice_lines',
  'recurring_journal_sources','clinic_refund_items','clinic_record_addenda','inpatient_rx_evidence','inpatient_rx_evidence_settings',
  'purchase_invoice_receipts','quest_new_customer_claims'];
begin
 -- Sources registered after 24 Oct with only a change trigger (refunds) or an
 -- insert-only one (immutable history reads) get the same standard pair, so every
 -- source keeps its private deletion record before cascades run.
 foreach t in array new_sources||array['clinic_refund_requests','clinic_refunds','clinic_history_reads'] loop
  if not exists(select 1 from public.activity_log_sources where entity=t) then
   raise exception 'A01 source % is not registered',t;
  end if;
  execute format('create or replace trigger a01_activity_change after insert or update on public.%I for each row execute function public.capture_activity_log()',t);
  execute format('create or replace trigger a01_activity_delete before delete on public.%I for each row execute function public.capture_activity_log()',t);
 end loop;
end$$;

-- Q01 lanjutan: quest progress that failed after payment can be re-applied safely.
--
-- Problem: the new-customer claim is written inside the payment finalizer, but quest progress is
-- written later by a separate apply_sale_staff_effects call whose error is only logged. A lost
-- call left the claim locked with no progress and nothing ever retried it.
--
-- Design (smallest change, no new state):
--   * apply_sale_staff_effects was already idempotent per sale (sale_staff_effects row), so a
--     retry can never double count; what was missing is (a) a retry and (b) retry correctness;
--   * (b) quest period, the new-customer period test and the streak day now come from the sale's
--     payment time (WIB) instead of the time of the call. For the normal call, seconds after
--     payment, this is the same day; for a late retry the progress lands in the period the sale
--     belongs to, and a retry of an older day never rewinds the streak;
--   * (a) apply_pending_sale_staff_effects() re-applies the caller's own paid, non-void, tracked
--     receipts (recent, still-open shift or back-office) that have no effect row yet, oldest first,
--     each in its own subtransaction. Checkouts call it after every paid sale (/kasir and
--     /pos/transaksi), so a failed call is repaired by the cashier's next checkout.
-- Grants, SECURITY DEFINER, search_path and the reversal contract are unchanged.

do $patch$
declare
  signature regprocedure := 'public.apply_sale_staff_effects(uuid)'::regprocedure;
  definition text := pg_get_functiondef(signature);
  day_old text := E' if exists(select 1 from public.sale_staff_effects where sale_id=s.id) then return jsonb_build_object(''applied'',true);end if;';
  day_new text := day_old
    || E'\n -- Q01 recovery: the period is the sale''s payment day (WIB), not the day of the (re)try.\n'
    || E' d:=(s.payments_finalized_at at time zone ''Asia/Jakarta'')::date;';
  streak_old text := ' if st.last_active_date is distinct from d then';
  streak_new text := ' if st.last_active_date is null or st.last_active_date<d then';
  count_of text;
begin
  if position('Q01 recovery' in definition) > 0 then
    return;                                        -- already applied (idempotent re-run)
  end if;
  foreach count_of in array array[day_old, streak_old] loop
    if (length(definition) - length(replace(definition, count_of, ''))) / length(count_of) <> 1 then
      raise exception 'Q01_RECOVERY_DRIFT: apply_sale_staff_effects changed; review before release';
    end if;
  end loop;
  definition := replace(definition, day_old, day_new);
  definition := replace(definition, streak_old, streak_new);
  execute definition;
end
$patch$;
-- CREATE OR REPLACE keeps the ACL; restate it so a fresh database matches exactly.
revoke all on function public.apply_sale_staff_effects(uuid) from public, anon, service_role;
grant execute on function public.apply_sale_staff_effects(uuid) to authenticated;

create index if not exists sales_staff_effects_pending_idx
  on public.sales (cashier_id, payments_finalized_at)
  where channel is null and quest_effects_tracked and voided_at is null and payments_finalized_at is not null;

create or replace function public.apply_pending_sale_staff_effects() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r record; v_applied integer := 0; v_failed integer := 0;
begin
  if auth.uid() is null or auth.role() is distinct from 'authenticated' then
    raise exception 'Akses ditolak' using errcode = '42501';
  end if;
  for r in
    select s.id from public.sales s
    where s.cashier_id = auth.uid() and s.channel is null and s.quest_effects_tracked
      and s.voided_at is null and s.payments_finalized_at is not null
      and s.payments_finalized_at > now() - interval '7 days'
      -- apply_sale_staff_effects only accepts a sale whose shift is still open (or back-office).
      and (s.shift_id is null or exists (select 1 from public.cashier_shifts cs
                                         where cs.id = s.shift_id and cs.status = 'open'))
      and not exists (select 1 from public.sale_staff_effects e where e.sale_id = s.id)
    order by s.payments_finalized_at, s.id
    limit 50
  loop
    begin
      perform public.apply_sale_staff_effects(r.id);   -- own checks + per-sale idempotency
      v_applied := v_applied + 1;
    exception when others then
      v_failed := v_failed + 1;                        -- one bad receipt never blocks the rest
    end;
  end loop;
  return jsonb_build_object('applied', v_applied, 'failed', v_failed);
end $$;
revoke all on function public.apply_pending_sale_staff_effects() from public, anon, authenticated, service_role;
grant execute on function public.apply_pending_sale_staff_effects() to authenticated;
comment on function public.apply_pending_sale_staff_effects() is
  'Q01: re-applies the caller''s own paid receipts whose staff quest effects are missing (idempotent per sale).';

insert into supabase_migrations.schema_migrations(version, name) values
